CREATE DATABASE IF NOT EXISTS agri CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE agri;

CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('farmer','admin') NOT NULL DEFAULT 'farmer', is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX ix_users_email (email));
CREATE TABLE refresh_tokens (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, jti CHAR(36) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX ix_refresh_tokens_user_id (user_id));
CREATE TABLE password_reset_tokens (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX ix_password_reset_tokens_user_id (user_id));
CREATE TABLE predictions (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, prediction_type VARCHAR(50) NOT NULL, input_data JSON NOT NULL, result_data JSON NOT NULL, confidence FLOAT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX ix_predictions_user_id (user_id), INDEX ix_predictions_prediction_type (prediction_type));
CREATE TABLE weather_logs (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, location VARCHAR(180) NOT NULL, observed_at DATETIME NOT NULL, data JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL, INDEX ix_weather_logs_user_id (user_id), INDEX ix_weather_logs_location (location), INDEX ix_weather_logs_observed_at (observed_at));
CREATE TABLE disease_detections (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, image_path VARCHAR(500) NOT NULL, crop VARCHAR(80) NULL, disease_name VARCHAR(150) NOT NULL, confidence FLOAT NOT NULL, treatment JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX ix_disease_detections_user_id (user_id));
CREATE TABLE reports (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, report_type VARCHAR(50) NOT NULL, file_path VARCHAR(500) NOT NULL, parameters JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX ix_reports_user_id (user_id));
CREATE TABLE notifications (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, category VARCHAR(40) NOT NULL, title VARCHAR(160) NOT NULL, message TEXT NOT NULL, payload JSON NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX ix_notifications_user_id (user_id), INDEX ix_notifications_category (category));
CREATE TABLE datasets (id INT AUTO_INCREMENT PRIMARY KEY, uploaded_by INT NOT NULL, name VARCHAR(150) NOT NULL UNIQUE, domain VARCHAR(60) NOT NULL, file_path VARCHAR(500) NOT NULL, row_count INT NOT NULL, metadata_json JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (uploaded_by) REFERENCES users(id) ON DELETE RESTRICT, INDEX ix_datasets_uploaded_by (uploaded_by), INDEX ix_datasets_domain (domain));
CREATE TABLE model_versions (id INT AUTO_INCREMENT PRIMARY KEY, dataset_id INT NULL, model_type VARCHAR(60) NOT NULL, version VARCHAR(60) NOT NULL, artifact_path VARCHAR(500) NOT NULL, metrics JSON NOT NULL, is_active BOOLEAN NOT NULL DEFAULT FALSE, trained_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (dataset_id) REFERENCES datasets(id) ON DELETE SET NULL, INDEX ix_model_versions_dataset_id (dataset_id), INDEX ix_model_versions_model_type (model_type));
CREATE TABLE chat_messages (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, role VARCHAR(20) NOT NULL, content TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX ix_chat_messages_user_id (user_id));
